{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Selegiline, a lipophilic tertiary amine with an aromatic ring, has an absolute oral bioavailability of only 4% in healthy volunteers after a 10 mg oral dose versus IV, indicating extensive first-pass metabolism; this high-transfer evidence supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Rotigotine/N-0437, a tertiary aminotetralin, is limited to subcutaneous and intravenous administration because of low oral bioavailability in humans; this high-transfer evidence supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Amitriptyline, a lipophilic tricyclic tertiary amine, has an absolute oral bioavailability around 45% in humans, providing a contradictory example that lipophilic basic amines can exceed 20% despite first-pass metabolism.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C47"],
      "claim": "Alfentanil, an N-phenyl-containing lipophilic opioid, has a baseline oral bioavailability of 37% in healthy volunteers, contradicting a simple low-F expectation for the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "Amiodarone, a highly lipophilic diethylamino-substituted drug, has a mean absolute oral bioavailability of 65% (range 29-100%), further contradicting low F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-transfer experimental evidence comes from selegiline and rotigotine, both showing low oral bioavailability (<20%) in humans due to extensive first-pass metabolism. Although some lower-transfer lipophilic tertiary amines (amitriptyline, alfentanil, amiodarone) have F >20%, the more transferable evidence supports low F for this N-phenyl-indanyl diethylaminopropylamine.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No metabolic stability or first-pass extraction data for the query.",
    "The 5-40% record for molecule 1 is ambiguous and not threshold-decisive.",
    "The query is not structurally identical to any evidence molecule, so transferability relies on shared lipophilic tertiary-amine features."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

